export type SalesPipelineFunnel = {
    accepted: SalesPipelineFunnelBucket;
    rejected: SalesPipelineFunnelBucket;
    waiting: SalesPipelineFunnelBucket;
    direct: SalesPipelineFunnelBucket;
    still_draft: SalesPipelineFunnelBucket;
};

export type SalesPipelineFunnelBucket = {
    count: number;
    hours: number;
};

/**
 * One funnel path's count + hours of approved jobs.
 *
 * Part of the answer to "Is the gap in our instant work or our quoted work?".
 */
export type SalesPipelineFunnelPath = {
    count: number;
    hours: number;
    hours_per_working_day: number | null;
};

/**
 * Two-path split of approved jobs: instant vs estimating.
 *
 * Instant = approval ≤1h after job_created (walk-ins, repeat customers).
 * Estimating = approval >1h after job_created (any pricing/thinking step).
 */
export type SalesPipelineFunnelPaths = {
    instant: SalesPipelineFunnelPath;
    estimating: SalesPipelineFunnelPath;
};

export type SalesPipelinePeriod = {
    start_date: string;
    end_date: string;
    rolling_window_weeks: number;
    trend_weeks: number;
    daily_approved_hours_target: number;
};

