/**
 * Read-only view over django-celery-beat's PeriodicTask.
 *
 * Frontend uses: id, name, task, enabled, last_run_at, schedule.
 * Schedule renders as a human string ("every 5 minutes" or cron expr) so the
 * UI doesn't need to know about IntervalSchedule vs CrontabSchedule shapes.
 */
export type ScheduledTask = {
    readonly id: number;
    /**
     * Short Description For This Task
     */
    name: string;
    /**
     * Task Name
     *
     * The Name of the Celery Task that Should be Run.  (Example: "proj.tasks.import_contacts")
     */
    task: string;
    /**
     * Set to False to disable the schedule
     */
    enabled?: boolean;
    /**
     * Last Run Datetime
     *
     * Datetime that the schedule last triggered the task to run. Reset to None if enabled is set to False.
     */
    readonly last_run_at: string | null;
    readonly schedule: string;
};

/**
 * Read-only view over django-celery-results' TaskResult.
 *
 * `task_name` here is the dotted Celery task name (e.g.
 * apps.workflow.tasks.xero_heartbeat_task). For Beat-scheduled tasks the
 * `periodic_task_name` is also populated (the human PeriodicTask.name).
 */
export type ScheduledTaskExecution = {
    readonly id: number;
    /**
     * Celery ID for the Task that was run
     */
    task_id: string;
    /**
     * Name of the Task which was run
     */
    task_name?: string | null;
    /**
     * Name of the Periodic Task which was run
     */
    periodic_task_name?: string | null;
    /**
     * Task State
     *
     * Current state of the task being run
     */
    status?: string;
    /**
     * Created DateTime
     *
     * Datetime field when the task result was created in UTC
     */
    readonly date_created: string;
    /**
     * Started DateTime
     *
     * Datetime field when the task was started in UTC
     */
    date_started?: string | null;
    /**
     * Completed DateTime
     *
     * Datetime field when the task was completed in UTC
     */
    readonly date_done: string;
    /**
     * Result Data
     *
     * The data returned by the task.  Use content_encoding and content_type fields to read.
     */
    readonly result: string | null;
    /**
     * Text of the traceback if the task generated one
     */
    traceback?: string | null;
    /**
     * Worker that executes the task
     */
    worker?: string | null;
    /**
     * Task Positional Arguments
     *
     * JSON representation of the positional arguments used with the task
     */
    task_args?: string | null;
    /**
     * Task Named Arguments
     *
     * JSON representation of the named arguments used with the task
     */
    task_kwargs?: string | null;
};

