/**
 * Serializer for CostLine model specifically for timesheet entries
 *
 * Architecture principle: Job data comes from CostSet->Job relationship,
 * NOT from metadata. This ensures data consistency and follows SRP:
 * - Metadata = timesheet-specific data (staff, date, billable, etc.)
 * - Relationship = job data (job_id, job_number, job_name, company)
 *
 * Benefits:
 * - No data duplication
 * - Always consistent with source Job
 * - Simplified queries and maintenance
 */
export type TimesheetCostLine = {
    readonly id: string;
    kind: CostLineKindEnum;
    /**
     * Description of this cost line
     */
    readonly desc: string | null;
    readonly quantity: number;
    readonly unit_cost: number;
    readonly unit_rev: number;
    /**
     * External references (e.g., time entry IDs, material IDs)
     */
    readonly ext_refs: unknown;
    /**
     * Additional metadata - structure varies by kind (see class docstring)
     */
    readonly meta: unknown;
    readonly created_at: string;
    readonly updated_at: string;
    /**
     * The date this cost should be attributed to for accounting purposes
     */
    readonly accounting_date: string;
    readonly xero_time_id: string | null;
    readonly xero_expense_id: string | null;
    readonly xero_last_modified: string | null;
    readonly xero_last_synced: string | null;
    /**
     * Indicates whether this line is approved or not by an office staff (when the line is created by a workshop worker)
     */
    readonly approved: boolean;
    /**
     * The Xero pay item for this time entry (leave type, earnings rate, etc.)
     */
    readonly xero_pay_item: string | null;
    /**
     * Staff member for actual time entries.
     */
    readonly staff: string | null;
    /**
     * Sequence number within a staff member's daily actual time entries.
     */
    readonly entry_seq: number | null;
    /**
     * The labour subtype for time lines (Workshop, Admin, Onsite, ...)
     */
    readonly labour_subtype: string | null;
    /**
     * Get total cost (quantity * unit_cost)
     */
    readonly total_cost: number;
    /**
     * Get total revenue (quantity * unit_rev)
     */
    readonly total_rev: number;
    readonly job_id: string;
    readonly job_number: number;
    readonly job_name: string;
    /**
     * Get company name with safe null handling
     */
    readonly company_name: string;
    readonly charge_out_rate: number;
    /**
     * Get staff wage rate for a time entry.
     */
    readonly wage_rate: number;
    readonly xero_pay_item_name: string;
    readonly labour_subtype_name: string;
};

